/**
 * @summary Initializes score icon
 *
 * @name score
 * @selector .slds-icon-score
 * @restrict span
 * @support dev-ready
 * @variant
 */
.slds-icon-score {
  display: inline-block;
  width: rem(5px);
  height: rem(5px);
  position: relative;
}

// We are variying opacity (instead of stroke & fill)
// because it is a more performant way of achieving this effect
.slds-icon-score__positive, .slds-icon-score__negative {
  position: absolute;
  opacity: 0;
  transition: opacity 0.4s ease-in-out;
  will-change: opacity;
  stroke-width: 1.125px;
}

/**
 * @summary Positive score icon
 *
 * @selector .slds-icon-score__positive
 * @restrict .slds-icon-score svg
 */
.slds-icon-score__positive {
  fill: var(--slds-g-color-success-base-50, #{$color-background-success-dark});
  stroke: var(--slds-g-color-success-base-50, #{$color-background-success-dark});
}

/**
 * @summary Negative score icon
 *
 * @selector .slds-icon-score__negative
 * @restrict .slds-icon-score svg
 */
.slds-icon-score__negative {
  fill: transparent;
  stroke: var(--slds-g-color-error-base-40, #{$color-background-destructive});
}

[data-slds-state="positive"] .slds-icon-score__positive,
[data-slds-state="negative"] .slds-icon-score__negative {
  opacity: 1;
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

// Base icon size and appearance
//
// 1. Each dot is an SVG <circle> element
// 2. Adds transitions when the strength changes.
//    Modifying the data-slds-strength attribute in JavaScript should
//    animate the dots nicely.
// 3. Let the browser know which properties are going to change,
//    enabling it to optimize rendering speed as best it can

/**
 * @summary Initializes strength icon
 *
 * @name strength
 * @selector .slds-icon-strength
 * @restrict span
 * @support dev-ready
 * @variant
 */
.slds-icon-strength {
  width: 1.6875rem;
  height: 0.4375rem;
  display: inline-block;

  circle { // 1
    stroke-width: 0.95px;
    fill: transparent;
    stroke: var(--slds-g-color-neutral-base-60, #{$palette-neutral-60});
    transition: // 2
      fill 0.4s ease-in-out,
      stroke 0.4s ease-in-out;
    will-change: fill, stroke; // 3
  }

  // Strength States
  //
  // The strength is controlled via the data-slds-strength attribute.
  //
  // These styles adapt the stroke and fill depending on the strength level.
  //
  // <svg data-slds-strength="[Number]">
  // 0. no active dots
  // (-)1. one active dot
  // (-)2. two active dots
  // (-)3. all dots active
  &[data-slds-strength="1"] circle:nth-child(1),
  &[data-slds-strength="2"] circle:nth-child(1),
  &[data-slds-strength="2"] circle:nth-child(2),
  &[data-slds-strength="3"] circle:nth-child(1),
  &[data-slds-strength="3"] circle:nth-child(2),
  &[data-slds-strength="3"] circle:nth-child(3) {
    fill: var(--slds-g-color-success-base-50, #{$color-text-success});
    stroke: var(--slds-g-color-success-base-50, #{$color-text-success});
  }

  &[data-slds-strength="-1"] circle:nth-child(1),
  &[data-slds-strength="-2"] circle:nth-child(1),
  &[data-slds-strength="-2"] circle:nth-child(2),
  &[data-slds-strength="-3"] circle:nth-child(1),
  &[data-slds-strength="-3"] circle:nth-child(2),
  &[data-slds-strength="-3"] circle:nth-child(3) {
    fill: var(--slds-g-color-palette-pink-90, #{$palette-pink-90});
    stroke: var(--slds-g-color-error-base-30, #{$color-background-error-dark});
  }

  /**
   * @summary Add .slds-is-animated to the SVG to enhance the icon with an animation.
   *
   * @selector .slds-is-animated
   * @restrict .slds-icon-strength
   */
  &.slds-is-animated {

    circle {
      // Adjust this value to add a delay to the whole animation
      $_strength-offset-delay: 1s;

      animation: slds-icon-strength-positive-load 0.4s $_strength-offset-delay ease-in-out alternate both paused;

      &:nth-child(2) {
        animation-delay: ($_strength-offset-delay + 0.4s);
      }

      &:nth-child(3) {
        animation-delay: ($_strength-offset-delay + 0.8s);
      }
    }

    &[data-slds-strength^="-"] circle {
      animation-name: slds-icon-strength-negative-load;
    }

    &[data-slds-strength="-1"] circle:nth-child(1),
    &[data-slds-strength="-2"] circle:nth-child(1),
    &[data-slds-strength="-2"] circle:nth-child(2),
    &[data-slds-strength="-3"] circle:nth-child(1),
    &[data-slds-strength="-3"] circle:nth-child(2),
    &[data-slds-strength="-3"] circle:nth-child(3),
    &[data-slds-strength="1"] circle:nth-child(1),
    &[data-slds-strength="2"] circle:nth-child(1),
    &[data-slds-strength="2"] circle:nth-child(2),
    &[data-slds-strength="3"] circle:nth-child(1),
    &[data-slds-strength="3"] circle:nth-child(2),
    &[data-slds-strength="3"] circle:nth-child(3) {
      animation-play-state: running;
    }
  }

  /**
   * @summary Add .slds-is-paused to the SVG to pause the icon with an animation.
   *
   * @selector .slds-is-paused
   * @restrict .slds-icon-strength
   */
  &.slds-is-paused circle {
    // scss-lint:disable ImportantRule
    /* stylelint-disable declaration-no-important */
    animation-play-state: paused !important;
    /* stylelint-enable declaration-no-important */
  }
}

// scss-lint:disable SingleLinePerProperty
// Improve readability of animations
// stylelint-disable
@keyframes slds-icon-strength-positive-load {
  0%   { fill: transparent; stroke: var(--slds-g-color-neutral-base-60, #{$palette-neutral-60}); }
  100% { fill: var(--slds-g-color-success-base-50, #{$color-text-success});
    stroke: var(--slds-g-color-success-base-50, #{$color-text-success}); }
}

@keyframes slds-icon-strength-negative-load {
  0%   { fill: transparent; stroke: var(--slds-g-color-neutral-base-60, #{$palette-neutral-60}); }
  100% { fill: var(--slds-g-color-palette-pink-90, #{$palette-pink-90}); stroke: var(--slds-g-color-error-base-40, #{$color-background-destructive}); }
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

// Circle's cirumference
$_icon-trend-circumference: 46.3385px; // r=7.375 * pi * 2

// Arrow path length
$_icon-trend-arrow-length: 20.15px;

// HACK: Trick minifiers so they don't minify 0px to 0,
// which breaks the animation in Edge
$_icon-trend-zero: 0.1px;

// HACK: a 1px stroke sitting on a pixel grid line (here: the arrow)
// doesn't get aliased well on non-retina displays,
// so we bump up the stroke-width to force a better anti-aliasing
// which improves rendering at small size
$_icon-trend-one: 1.125px;

/**
 * @summary Initializes trend icon
 *
 * @name trend
 * @selector .slds-icon-trend
 * @restrict span
 * @support dev-ready
 * @variant
 */
.slds-icon-trend {
  width: 1rem;
  height: 1rem;
  display: inline-block;

  /**
   * @summary Add .slds-is-animated to the SVG to enhance the icon with an animation.
   *
   * @selector .slds-is-animated
   * @restrict .slds-icon-trend
   */
  &.slds-is-animated {

    .slds-icon-trend__arrow {
      animation: slds-icon-trend-arrow ($duration-slowly * 2) ($duration-slowly) ease-in-out both;
    }

    .slds-icon-trend__circle {
      animation: slds-icon-trend-circle ($duration-slowly * 2) ease-in-out both;
    }
  }

  /**
   * @summary Add .slds-is-paused to the SVG to pause the icon with an animation.
   *
   * @selector .slds-is-paused
   * @restrict .slds-icon-trend
   */
  &.slds-is-paused {

    .slds-icon-trend__arrow,
    .slds-icon-trend__circle {
      animation-play-state: paused;
    }
  }
}

.slds-icon-trend[data-slds-trend="down"] {
  color: var(--slds-g-color-error-base-30, #{$color-background-error-dark});
  transform: rotate(45deg);
}

.slds-icon-trend[data-slds-trend="neutral"] {
  color: var(--slds-g-color-neutral-base-50, #{$palette-neutral-60});
}

.slds-icon-trend[data-slds-trend="up"] {
  color: var(--slds-g-color-success-base-50, #{$color-background-success-dark});
  transform: rotate(-45deg);
}

.slds-icon-trend__arrow,
.slds-icon-trend__circle {
  stroke: currentColor;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: $_icon-trend-one;
}

/**
 * @summary Arrow element inside of trend icon
 *
 * @selector .slds-icon-trend__arrow
 * @restrict .slds-icon-trend path
 */
.slds-icon-trend__arrow {
  stroke-dashoffset: $_icon-trend-zero;
  stroke-dasharray: $_icon-trend-arrow-length * 2 - $_icon-trend-one;
}

/**
 * @summary Circle element inside of trend icon
 *
 * @selector .slds-icon-trend__circle
 * @restrict .slds-icon-trend circle
 */
.slds-icon-trend__circle {
  stroke-dasharray: ($_icon-trend-circumference - 4px), $_icon-trend-circumference;
}

@keyframes slds-icon-trend-arrow {

  from {
    stroke-dashoffset: $_icon-trend-arrow-length * 2;
  }
}

@keyframes slds-icon-trend-circle {

  from {
    stroke-dasharray: $_icon-trend-zero, $_icon-trend-circumference;
  }
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

/**
 * @summary Initializes typing icon
 *
 * @name typing
 * @selector .slds-icon-typing
 * @restrict span
 * @support dev-ready
 * @variant
 */

.slds-icon-typing {
  display: inline-block;
  padding: $spacing-xx-small 0;

  /**
   * @summary Add when you wish to animate the dots
   *
   * @selector .slds-is-animated
   * @restrict .slds-icon-typing
   * @modifier
   */
  &.slds-is-animated {

    .slds-icon-typing__dot {
      animation: slds-icon-typing__dot-first 1.2s infinite ease-in-out;
    }

    .slds-icon-typing__dot:nth-child(1) {
      animation-name: slds-icon-typing__dot-first;
    }

    .slds-icon-typing__dot:nth-child(2) {
      animation-name: slds-icon-typing__dot-second;
    }

    .slds-icon-typing__dot:nth-child(3) {
      animation-name: slds-icon-typing__dot-third;
    }
  }

  /**
   * @summary Add when you wish to pause the dots animation
   *
   * @selector .slds-is-paused
   * @restrict .slds-icon-typing
   * @modifier
   */
  &.slds-is-paused {

    .slds-icon-typing__dot {
      animation-play-state: paused;
    }
  }
}

/**
 * @summary Dots within the typing icon
 *
 * @selector .slds-icon-typing__dot
 * @restrict .slds-icon-typing span
 */
.slds-icon-typing__dot {
  background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  border-radius: $border-radius-circle;
  display: inline-block;
  height: $typing-icon-dot-size;
  margin: 0 $spacing-xxx-small;
  width: $typing-icon-dot-size;
}

@keyframes slds-icon-typing__dot-first {

  0% {
    background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  }

  16% {
    background-color: var(--slds-g-color-neutral-base-60, #{$typing-icon-dot-color-background-gray-dark});
  }

  33%,
  100% {
    background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  }
}

@keyframes slds-icon-typing__dot-second {

  0%,
  33% {
    background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  }

  50% {
    background-color: var(--slds-g-color-neutral-base-60, #{$typing-icon-dot-color-background-gray-dark});
  }

  67%,
  100% {
    background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  }
}

@keyframes slds-icon-typing__dot-third {

  0%,
  67% {
    background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  }

  83% {
    background-color: var(--slds-g-color-neutral-base-60, #{$typing-icon-dot-color-background-gray-dark});
  }

  100% {
    background-color: var(--slds-g-color-neutral-base-80, #{$typing-icon-dot-color-background-gray});
  }
}

// Lightning Design System 2.264.1
// Copyright (c) 2015-present, salesforce.com, inc. All rights reserved
// Licensed under BSD 3-Clause - see LICENSE.txt or git.io/sfdc-license

// I need to associate slds-icon-animated with something since there isn't a base variant

// All SLDS size classes like `slds-r1` and `slds-r9` in one string.
// This is faster for style calculation than `[class*="slds-r"]`.
/// @private
@function all-slds-r () {
  $result: '';
  @for $i from 1 through 9 {
    $result: "#{$result}, .slds-r#{$i}";
  }

  @return str-slice($result, 3); // Remove initial ", "
}

/**
 * @summary Containing actionable element that holds the waffle icon
 *
 * @name waffle
 * @selector .slds-icon-waffle_container
 * @restrict button
 * @support dev-ready
 * @variant
 */
.slds-icon-waffle_container {
  border: 0;
  outline: 0;

  &:hover,
  &:focus {

    #{all-slds-r()} {
      animation: slds-icon-waffle-throb 2 200ms alternate;
    }

    .slds-r1,
    .slds-r2,
    .slds-r3 {
      background-color: var(--slds-g-color-brand-base-50,#418fde);
    }

    .slds-r4,
    .slds-r5,
    .slds-r7 {
      background-color: var(--slds-g-color-warning-base-70,#ed8b00);
    }

    .slds-r6,
    .slds-r8,
    .slds-r9 {
      background-color: var(--slds-g-color-palette-yellow-80,#ffb60f);
    }

    .slds-r2,
    .slds-r4 {
      transition-delay: 50ms;
      animation-delay: 50ms;
    }

    .slds-r3,
    .slds-r5,
    .slds-r7 {
      transition-delay: 100ms;
      animation-delay: 100ms;
    }

    .slds-r6,
    .slds-r8 {
      transition-delay: 150ms;
      animation-delay: 150ms;
    }

    .slds-r9 {
      transition-delay: 200ms;
      animation-delay: 200ms;
    }
  }
}

/**
 * @summary Element container circles for the waffle icon
 *
 * @selector .slds-icon-waffle
 * @restrict .slds-icon-waffle_container > span
 */
.slds-icon-waffle {
  @include square(rem(21px));
  position: relative;
  display: block;
  cursor: pointer;

  #{all-slds-r()} {
    @include square(rem(5px));
    background-color: var(--slds-g-color-neutral-base-50, #{$color-background-icon-waffle});
    display: inline-block;
    position: absolute;
    border-radius: $border-radius-circle;
    transition: background-color 100ms;
    transform-origin: 50% 50%;
    will-change: scale, background-color;
    border: 2px solid transparent;
  }

  // Positioning
  .slds-r1 {
    top: 0;
    left: 0;
  }

  .slds-r2 {
    top: 0;
    left: rem(8px);
  }

  .slds-r3 {
    top: 0;
    right: 0;
  }

  .slds-r4 {
    top: rem(8px);
    left: 0;
  }

  .slds-r5 {
    top: rem(8px);
    left: rem(8px);
  }

  .slds-r6 {
    top: rem(8px);
    right: 0;
  }

  .slds-r7 {
    bottom: 0;
    left: 0;
  }

  .slds-r8 {
    bottom: 0;
    left: rem(8px);
  }

  .slds-r9 {
    bottom: 0;
    right: 0;
  }

  // Default delays
  // scss-lint:disable MergeableSelector
  .slds-r1 {
    transition-delay: 200ms;
  }

  .slds-r2,
  .slds-r4 {
    transition-delay: 150ms;
  }

  .slds-r3,
  .slds-r5,
  .slds-r7 {
    transition-delay: 100ms;
  }

  .slds-r6,
  .slds-r8 {
    transition-delay: 50ms;
  }
}

@keyframes slds-icon-waffle-throb {

  to {
    transform: scale(1.5);
  }
}
